async function callHealth(): Promise<void> {
  const started = Date.now();
  try {
    const res = await fetch("http://203.0.113.10/health", {
      signal: AbortSignal.timeout(5000), // 5초 뒤 중단
    });
    console.log("HTTP 응답", res.status);
  } catch (err) {
    const name = err instanceof Error ? err.name : "unknown";
    console.log("실패:", name, `${Date.now() - started}ms`);
  }
}

// dns: true 통과, false 실패, null 시도하지 않음(IP 주소로 직접 호출)
type Probe = { dns: boolean | null; ping: boolean; tcp: boolean; http: number | null };

function lastPassed(p: Probe): string {
  if (p.dns === false) return "이름 해석에서 멈춤";
  if (!p.tcp) {
    return p.ping
      ? "IP 도달까지 확인, TCP 포트 연결에서 멈춤"
      : "TCP 포트 연결 실패(IP 도달도 미확인)";
  }
  if (p.http === null) return "TCP 연결까지 확인, HTTP 응답 없음";
  return `HTTP 응답 ${p.http}`;
}

console.log(lastPassed({ dns: null, ping: true, tcp: false, http: null }));
console.log(lastPassed({ dns: null, ping: false, tcp: true, http: 200 }));
console.log(lastPassed({ dns: true, ping: true, tcp: true, http: 503 }));
